files.content:
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #121016;
  --card-bg: #1c1822;
  --wax-color: #e0d0b8;
  --wax-shadow: #b39f82;
  --flame-outer: #ff9900;
  --flame-inner: #ffe600;
  --text-main: #f5eedf;
  --text-muted: #9f9689;
  --btn-primary: #e67e22;
  --btn-primary-hover: #d35400;
  --btn-secondary: #4a4238;
  --btn-secondary-hover: #5d5346;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: var(--font-family);
  font-size: 16px;
  padding: 20px;
}

.card {
  background-color: var(--card-bg);
  border: 4px solid #2b2535;
  box-shadow: 0 12px 0 #000000;
  border-radius: 4px;
  padding: 32px 24px;
  width: 100%;
  max-width: 380px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 20px;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #ffcc66;
  text-shadow: 2px 2px #000;
}

.scene {
  width: 100%;
  height: 220px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  position: relative;
  background: #141119;
  border: 4px solid #000;
  border-radius: 4px;
  padding-bottom: 24px;
}

.candle-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}

.flame {
  width: 16px;
  height: 28px;
  background-color: var(--flame-outer);
  position: relative;
  border-radius: 8px 8px 4px 4px;
  box-shadow:
    0 0 16px rgba(255, 153, 0, 0.8),
    0 0 32px rgba(255, 230, 0, 0.4);
  animation: flicker 0.15s infinite alternate ease-in-out;
  margin-bottom: 2px;
}

.flame-core {
  position: absolute;
  bottom: 2px;
  left: 4px;
  width: 8px;
  height: 14px;
  background-color: var(--flame-inner);
  border-radius: 4px 4px 2px 2px;
}

.flame.hidden {
  visibility: hidden;
  animation: none;
}

@keyframes flicker {
  0% {
    transform: scale(1) translateY(0);
    filter: brightness(1);
  }
  100% {
    transform: scale(0.95, 1.08) translateY(-2px);
    filter: brightness(1.2);
  }
}

.wick {
  width: 4px;
  height: 10px;
  background-color: #2b1f1d;
  border-radius: 2px;
}

.candle-body {
  width: 64px;
  height: 120px;
  background-color: var(--wax-color);
  border-left: 6px solid #fff5e6;
  border-right: 8px solid var(--wax-shadow);
  box-shadow: inset 0 -4px 0 var(--wax-shadow);
  position: relative;
  min-height: 8px;
  image-rendering: pixelated;
}

.wax-drip {
  position: absolute;
  background-color: #fff5e6;
  width: 6px;
  top: 0;
  border-radius: 0 0 3px 3px;
}

.drip-left {
  left: 6px;
  height: 18px;
}

.drip-right {
  left: 20px;
  height: 10px;
}

.candle-base {
  width: 110px;
  height: 12px;
  background-color: #4a3e35;
  border-top: 3px solid #6e5e52;
  border-bottom: 3px solid #231c18;
  box-shadow: 0 4px 0 #000000;
}

.status-area {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.timer-display {
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: 3px;
  font-variant-numeric: tabular-nums;
  color: #ffea9f;
  text-shadow: 2px 2px 0 #000;
}

.status-message {
  font-size: 1rem;
  color: var(--text-muted);
  font-weight: 500;
  min-height: 1.5rem;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 10px 18px;
  border: 3px solid #000;
  cursor: pointer;
  color: #ffffff;
  box-shadow: 3px 3px 0 #000;
  outline: none;
  transition: background-color 0.1s, transform 0.05s, box-shadow 0.05s;
  flex: 1 1 90px;
}

.btn:focus-visible {
  outline: 3px solid #ffe600;
  outline-offset: 2px;
}

.btn:hover:not(:disabled) {
  filter: brightness(1.1);
}

.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 #000;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
  filter: grayscale(0.5);
}

.btn-primary {
  background-color: var(--btn-primary);
}

.btn-secondary {
  background-color: var(--btn-secondary);
}

.btn-tertiary {
  background-color: #312b3b;
}

(() => {
  const TOTAL_SECONDS = 180;
  const MAX_HEIGHT_PX = 120;
  const MIN_HEIGHT_PX = 8;

  let remainingSeconds = TOTAL_SECONDS;
  let timerInterval = null;
  let isBurning = false;

  const candleBody = document.getElementById('candleBody');
  const flame = document.getElementById('flame');
  const timerDisplay = document.getElementById('timerDisplay');
  const statusMessage = document.getElementById('statusMessage');
  const lightBtn = document.getElementById('lightBtn');
  const blowOutBtn = document.getElementById('blowOutBtn');
  const resetBtn = document.getElementById('resetBtn');

  function formatTime(totalSec) {
    const mins = Math.floor(totalSec / 60);
    const secs = totalSec % 60;
    const paddedSecs = secs < 10 ? `0${secs}` : `${secs}`;
    return `${mins}:${paddedSecs}`;
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(remainingSeconds);

    const progress = remainingSeconds / TOTAL_SECONDS;
    const currentHeight = MIN_HEIGHT_PX + progress * (MAX_HEIGHT_PX - MIN_HEIGHT_PX);
    candleBody.style.height = `${currentHeight}px`;
  }

  function setBurntOutState() {
    stopTimer();
    isBurning = false;
    remainingSeconds = 0;
    updateDisplay();
    flame.classList.add('hidden');
    statusMessage.textContent = 'Burnt out';
    timerDisplay.textContent = '0:00';
    candleBody.style.height = `${MIN_HEIGHT_PX}px`;
    lightBtn.disabled = true;
    blowOutBtn.disabled = true;
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds -= 1;
      updateDisplay();
      if (remainingSeconds <= 0) {
        setBurntOutState();
      }
    } else {
      setBurntOutState();
    }
  }

  function startTimer() {
    if (isBurning || remainingSeconds <= 0) return;
    isBurning = true;
    flame.classList.remove('hidden');
    statusMessage.textContent = 'Burning...';
    lightBtn.disabled = true;
    blowOutBtn.disabled = false;

    timerInterval = setInterval(tick, 1000);
  }

  function stopTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  function pauseTimer() {
    if (!isBurning) return;
    isBurning = false;
    stopTimer();
    flame.classList.add('hidden');
    statusMessage.textContent = 'Blown out (Paused)';
    lightBtn.disabled = false;
    blowOutBtn.disabled = true;
  }

  function resetTimer() {
    stopTimer();
    isBurning = false;
    remainingSeconds = TOTAL_SECONDS;
    updateDisplay();
    flame.classList.add('hidden');
    statusMessage.textContent = 'Ready to light';
    lightBtn.disabled = false;
    blowOutBtn.disabled = true;
  }

  lightBtn.addEventListener('click', startTimer);
  blowOutBtn.addEventListener('click', pauseTimer);
  resetBtn.addEventListener('click', resetTimer);

  updateDisplay();
})();
